<?php require __DIR__.'/../bootstrap.php';admin_only();verify_csrf();$id=(int)($_GET['id']??0);$p=['name'=>'','slug'=>'','sku'=>'','description'=>'','price'=>0,'stock'=>0,'image'=>'','category_id'=>'','active'=>1];if($id){$s=$pdo->prepare('SELECT * FROM products WHERE id=?');$s->execute([$id]);$p=$s->fetch()?:$p;}if($_SERVER['REQUEST_METHOD']==='POST'){$data=[trim($_POST['name']),trim($_POST['slug']),trim($_POST['sku']),trim($_POST['description']),(int)$_POST['price'],(int)$_POST['stock'],trim($_POST['image']),$_POST['category_id']!==''?(int)$_POST['category_id']:null,isset($_POST['active'])?1:0];try{if($id){$s=$pdo->prepare('UPDATE products SET name=?,slug=?,sku=?,description=?,price=?,stock=?,image=?,category_id=?,active=? WHERE id=?');$s->execute([...$data,$id]);}else{$s=$pdo->prepare('INSERT INTO products(name,slug,sku,description,price,stock,image,category_id,active) VALUES(?,?,?,?,?,?,?,?,?)');$s->execute($data);}flash('ok','ذخیره شد.');redirect('admin/products.php');}catch(Throwable $e){$error='خطا: '.$e->getMessage();}}$cats=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();$title=$id?'ویرایش محصول':'محصول جدید';require __DIR__.'/../partials/header.php';?><h1><?=$title?></h1><?php if(!empty($error)): ?><div class="alert err"><?=e($error)?></div><?php endif; ?><div class="panel"><form method="post"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><div class="form-grid"><div class="field"><label>نام</label><input name="name" value="<?=e($p['name'])?>" required></div><div class="field"><label>Slug</label><input name="slug" value="<?=e($p['slug'])?>" required></div><div class="field"><label>SKU</label><input name="sku" value="<?=e($p['sku'])?>" required></div><div class="field"><label>دسته</label><select name="category_id"><option value="">بدون دسته</option><?php foreach($cats as $c): ?><option value="<?=$c['id']?>" <?=$p['category_id']==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="field"><label>قیمت</label><input type="number" name="price" value="<?=$p['price']?>" required></div><div class="field"><label>موجودی</label><input type="number" name="stock" value="<?=$p['stock']?>" required></div><div class="field" style="grid-column:1/-1"><label>لینک تصویر</label><input name="image" value="<?=e($p['image'])?>"></div><div class="field" style="grid-column:1/-1"><label>توضیحات</label><textarea name="description" rows="7"><?=e($p['description'])?></textarea></div></div><label><input type="checkbox" name="active" <?=$p['active']?'checked':''?>> فعال باشد</label><div style="margin-top:15px"><button class="btn">ذخیره</button></div></form></div><?php require __DIR__.'/../partials/footer.php'; ?>
